spec.section:
# context-transfer-result.schema.json

Generated, complete JSON Schema reference. Required/default/conditional rules are not inferred.

```json
{
  "$id": "https://coding-hermes.local/chd32/schemas/context-transfer-result.schema.json",
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "additionalProperties": false,
  "properties": {
    "imported_refs": {
      "items": {
        "minLength": 1,
        "type": "string"
      },
      "minItems": 1,
      "type": "array"
    },
    "readback_ref": {
      "pattern": "^/chd/effective-readback/[A-Za-z0-9._/-]+$",
      "type": "string"
    },
    "request_id": {
      "pattern": "^ctxreq-[a-z0-9-]+$",
      "type": "string"
    },
    "result_id": {
      "pattern": "^ctxres-[a-z0-9-]+$",
      "type": "string"
    },
    "schema_version": {
      "const": 1
    },
    "source_request": {
      "pattern": "^/chd/context-transfer/requests/ctxreq-[a-z0-9-]+$",
      "type": "string"
    },
    "status": {
      "const": "accepted"
    },
    "target_bond_id": {
      "pattern": "^b-[0-9]{8}-[0-9]{4}-[a-z0-9-]+$",
      "type": "string"
    },
    "target_policy_snapshot_id": {
      "pattern": "^sp-[A-Za-z0-9._-]+$",
      "type": "string"
    },
    "target_session_id": {
      "minLength": 1,
      "type": "string"
    }
  },
  "required": [
    "schema_version",
    "request_id",
    "result_id",
    "status",
    "source_request",
    "target_session_id",
    "target_bond_id",
    "target_policy_snapshot_id",
    "imported_refs",
    "readback_ref"
  ],
  "title": "CHD cross-profile context transfer result",
  "type": "object"
}
```
